	minterRealms.Remove(addr.String())
	chain.Emit(
		UnsetMinterRealmEvent,
		"pkgPath", pkgPath,
		"address", addr.String(),
	)
}

func IsMinterRealm(addr address) bool {
	return minterRealms.Has(addr.String())
}

func minterRealmAddress(pkgPath string) address {
	if pkgPath == "" {
		panic("package path is required")
	}
	if !strings.HasPrefix(pkgPath, "gno.land/r/") || pkgPath == "gno.land/r/" {
		panic("invalid package path")
	}
	return chain.PackageAddress(pkgPath)
}

package equipment

import (
	"chain/runtime/unsafe"
	"net/url"
	"strconv"
	"time"

	"gno.land/p/akkadia/beta/accesscontrol"
	"gno.land/p/akkadia/beta/grc721"
	"gno.land/p/nt/bptree/v0"
	"gno.land/r/akkadia/beta/admin"
)

const (
	definitionIDKey            = "definitionId"
	tokenIDKey                 = "tokenId"
	createdAtKey               = "created_at"
	maxEquipmentTokenID uint64 = 18446744073709551615
)

var (
	equipmentToken    = grc721.NewBasicNFT("Akkadia Equipment", "AEQP")
	equipmentMetadata *bptree.BPTree
	ownerTokenIDs     *bptree.BPTree
	latestTokenID     uint64
)

func init() { resetEquipmentState() }

func resetEquipmentState() {
	equipmentToken = grc721.NewBasicNFT("Akkadia Equipment", "AEQP")
	equipmentMetadata = bptree.NewBPTree32()
	ownerTokenIDs = bptree.NewBPTree32()
	minterRealms = bptree.NewBPTree32()
	listLimit = 100
	latestTokenID = 0
}

func Mint(cur realm, recipient address, definitionID uint32, attrKeys, attrValues string) uint64 {
	accesscontrol.MustGetAdminOrOperatorCaller(0, cur, admin.IsAdmin, admin.IsOperator)
	assertEquipmentNoCoins()
	return mintEquipment(cross(cur), recipient, definitionID, attrKeys, attrValues)
}

func MintFromRealm(cur realm, recipient address, definitionID uint32, attrKeys, attrValues string) uint64 {
	mustGetMinterRealmCaller(0, cur)
	if unsafe.OriginCaller() != recipient {
		panic("equipment recipient must be origin caller")
	}
	return mintEquipment(cross(cur), recipient, definitionID, attrKeys, attrValues)
}

func GetMetadata(tokenID uint64) map[string]string {
	return copyStringMap(mustGetEquipmentMetadata(tokenID))
}

func SetMetadata(cur realm, tokenID uint64, attrKeys, attrValues string) {
	accesscontrol.MustGetAdminOrOperatorCaller(0, cur, admin.IsAdmin, admin.IsOperator)
	assertEquipmentNoCoins()
	setEquipmentMetadata(tokenID, attrKeys, attrValues)
}

func SetMetadataFromRealm(cur realm, tokenID uint64, attrKeys, attrValues string) {
	mustGetMinterRealmCaller(0, cur)
	if unsafe.OriginCaller() != OwnerOf(tokenID) {
		panic("equipment owner must be origin caller")
	}
	setEquipmentMetadata(tokenID, attrKeys, attrValues)
}

func GetOwnedCount(owner address) int {
	if !owner.IsValid() {
		panic("invalid equipment owner")
	}
	ids, found := getOwnerTokenIDs(owner)
	if !found {
		return 0
	}
	return ids.Size()
}

func ListByOwner(owner address, page, count int) []map[string]string {
	if !owner.IsValid() {
		panic("invalid equipment owner")
	}
	assertEquipmentListPageCount(page, count)
	ids, found := getOwnerTokenIDs(owner)
	if !found {
		return []map[string]string{}
	}
	result := []map[string]string{}
	ids.IterateByOffset((page-1)*count, count, func(key string, _ any) bool {
		tokenID := parseUint64Key(key)
		row := GetMetadata(tokenID)
		row[tokenIDKey] = strconv.FormatUint(tokenID, 10)
		result = append(result, row)
		return false
	})
	return result
}

func Name() string   { return equipmentToken.Name() }
func Symbol() string { return equipmentToken.Symbol() }

func OwnerOf(tokenID uint64) address {
	owner, err := equipmentToken.OwnerOf(equipmentTokenID(tokenID))
	if err != nil {
		panic("equipment owner query failed: " + err.Error())
	}
	return owner
}

func Has(tokenID uint64) bool {
	_, err := equipmentToken.OwnerOf(equipmentTokenID(tokenID))
	return err == nil
}

func GetLatestTokenID() uint64 {
	return latestTokenID
}

func BalanceOf(owner address) int64 {
	if !owner.IsValid() {
		panic("invalid equipment owner")
	}
	balance, err := equipmentToken.BalanceOf(owner)
	if err != nil {
		panic("equipment balance query failed: " + err.Error())
	}
	return balance
}

func GetApproved(tokenID uint64) address {
	approved, err := equipmentToken.GetApproved(equipmentTokenID(tokenID))
	if err != nil {
		panic("equipment approval query failed: " + err.Error())
	}
	return approved
}

func IsApprovedForAll(owner, operator address) bool {
	return equipmentToken.IsApprovedForAll(owner, operator)
}

func Approve(cur realm, operator address, tokenID uint64) {
	caller := accesscontrol.MustGetUserCaller(0, cur)
	assertEquipmentNoCoins()
	if err := equipmentToken.Approve(caller, operator, equipmentTokenID(tokenID)); err != nil {
		panic("equipment approval failed: " + err.Error())
	}
}

func SetApprovalForAll(cur realm, operator address, approved bool) {
	caller := accesscontrol.MustGetUserCaller(0, cur)
	assertEquipmentNoCoins()
	if err := equipmentToken.SetApprovalForAll(caller, operator, approved); err != nil {
		panic("equipment operator approval failed: " + err.Error())
	}
}

func TransferFrom(cur realm, from, to address, tokenID uint64) {
	caller := accesscontrol.MustGetUserCaller(0, cur)
	assertEquipmentNoCoins()
	if err := equipmentToken.TransferFrom(caller, from, to, equipmentTokenID(tokenID)); err != nil {
		panic("equipment transfer failed: " + err.Error())
	}
	if from != to {
		removeOwnerTokenID(from, tokenID)
		addOwnerTokenID(to, tokenID)
	}
}

func Burn(cur realm, tokenID uint64) {
	caller := accesscontrol.MustGetUserCaller(0, cur)
	assertEquipmentNoCoins()
	owner := OwnerOf(tokenID)
	approved, err := equipmentToken.GetApproved(equipmentTokenID(tokenID))
	if caller != owner && !equipmentToken.IsApprovedForAll(owner, caller) && (err != nil || approved != caller) {
		panic("equipment owner or approved operator required")
	}
	burnEquipment(tokenID, owner)
}

func BurnFromRealm(cur realm, tokenID uint64) {
	mustGetMinterRealmCaller(0, cur)
	owner := OwnerOf(tokenID)
	if unsafe.OriginCaller() != owner {
		panic("equipment owner must be origin caller")
	}
	burnEquipment(tokenID, owner)
}

func mintEquipment(cur realm, recipient address, definitionID uint32, attrKeys, attrValues string) uint64 {
	if !recipient.IsValid() || recipient == cur.Address() {
		panic("invalid equipment recipient")
	}
	attrs := parseEquipmentAttributes(attrKeys, attrValues)
	tokenID := allocateTokenID()
	if err := equipmentToken.Mint(recipient, equipmentTokenID(tokenID)); err != nil {
		panic("equipment mint failed: " + err.Error())
	}
	attrs[definitionIDKey] = strconv.FormatUint(uint64(definitionID), 10)
	attrs[createdAtKey] = strconv.FormatInt(time.Now().Unix(), 10)
	equipmentMetadata.Set(uint64Key(tokenID), attrs)
	addOwnerTokenID(recipient, tokenID)
	return tokenID
}

func allocateTokenID() uint64 {
	if latestTokenID == maxEquipmentTokenID {
		panic("equipment token id exhausted")
	}
	latestTokenID++
	return latestTokenID
}

func mustGetEquipmentMetadata(tokenID uint64) map[string]string {
	value := equipmentMetadata.Get(uint64Key(tokenID))
	if value == nil {
		panic("equipment metadata not found: " + strconv.FormatUint(tokenID, 10))
	}
	return value.(map[string]string)
}

func setEquipmentMetadata(tokenID uint64, attrKeys, attrValues string) {
	current := mustGetEquipmentMetadata(tokenID)
	attrs := parseEquipmentAttributes(attrKeys, attrValues)
	attrs[definitionIDKey] = current[definitionIDKey]
	attrs[createdAtKey] = current[createdAtKey]
	equipmentMetadata.Set(uint64Key(tokenID), attrs)
}

func parseEquipmentAttributes(attrKeys, attrValues string) map[string]string {
	attrs := parseAttributesCSV(attrKeys, attrValues)
	if _, found := attrs[definitionIDKey]; found {
		panic("reserved key: " + definitionIDKey)
	}
	if _, found := attrs[tokenIDKey]; found {
		panic("reserved key: " + tokenIDKey)
	}
	if _, found := attrs[createdAtKey]; found {
		panic("reserved key: " + createdAtKey)
	}
	return attrs
}

func burnEquipment(tokenID uint64, owner address) {
	if err := equipmentToken.Burn(equipmentTokenID(tokenID)); err != nil {
		panic("equipment burn failed: " + err.Error())
	}
	if _, removed := equipmentMetadata.Remove(uint64Key(tokenID)); !removed {
		panic("equipment metadata not found: " + strconv.FormatUint(tokenID, 10))
	}
	removeOwnerTokenID(owner, tokenID)
}

func mustGetMinterRealmCaller(_ int, rlm realm) address {
	accesscontrol.AssertCurrentRealm(0, rlm)
	prev := rlm.Previous()
	if prev.IsUserCall() {
		panic("user calls not allowed: function must be called by a realm")
	}
	caller := prev.Address()
	if !IsMinterRealm(caller) {
		panic("minter realm required")
	}
	return caller
}

func assertEquipmentNoCoins() {
	if len(unsafe.OriginSend()) != 0 {
		panic("attached coins not allowed")
	}
}

func assertEquipmentListPageCount(page, count int) {
	if page < 1 {
		panic("page must be at least 1")
	}
	if count < 1 {
		panic("count must be at least 1")
	}
	if count > listLimit {
		panic("count exceeds listLimit (max: " + strconv.Itoa(listLimit) + ")")
	}
}

func addOwnerTokenID(owner address, tokenID uint64) {
	value := ownerTokenIDs.Get(owner.String())
	var ids *bptree.BPTree
	if value != nil {
		ids = value.(*bptree.BPTree)
	} else {
		ids = bptree.NewBPTree32()
		ownerTokenIDs.Set(owner.String(), ids)
	}
	ids.Set(uint64Key(tokenID), true)
}

func removeOwnerTokenID(owner address, tokenID uint64) {
	ids, found := getOwnerTokenIDs(owner)
	if !found {
		return
	}
	ids.Remove(uint64Key(tokenID))
}

func getOwnerTokenIDs(owner address) (*bptree.BPTree, bool) {
	value := ownerTokenIDs.Get(owner.String())
	if value == nil {
		return nil, false
	}
	return value.(*bptree.BPTree), true
}

func equipmentTokenID(tokenID uint64) grc721.TokenID {
	return grc721.TokenID(strconv.FormatUint(tokenID, 10))
}

func uint64Key(id uint64) string {
	s := strconv.FormatUint(id, 10)
	if len(s) >= 20 {
		return s
	}
	return "00000000000000000000"[len(s):] + s
}

func parseUint64Key(key string) uint64 {
	id, err := strconv.ParseUint(key, 10, 64)
	if err != nil {
		panic("invalid uint64 key: " + key)
	}
	return id
}

func copyStringMap(source map[string]string) map[string]string {
	result := map[string]string{}
	for key, value := range source {
		result[key] = value
	}
	return result
}

// parseAttributesCSV accepts comma-separated keys and URL-encoded values.
// Empty keys and values produce an empty attribute map so mint can store
// definitionId and created_at alone.
func parseAttributesCSV(keys, values string) map[string]string {
	if keys == "" && values == "" {
		return map[string]string{}
	}

	result := map[string]string{}
	keyStart, valStart := 0, 0
	keyIdx, valIdx := 0, 0
	for {
		for keyIdx < len(keys) && keys[keyIdx] != ',' {
			keyIdx++
		}
		for valIdx < len(values) && values[valIdx] != ',' {
			valIdx++
		}

		key := keys[keyStart:keyIdx]
		if key == "" {
			panic("attributes key must be not empty")
		}
		if _, found := result[key]; found {
			panic("attributes key duplicated: " + key)
		}

		value, err := url.PathUnescape(values[valStart:valIdx])
		if err != nil {
			panic("attributes value URL decode failed: " + key)
		}
		result[key] = value

		keyEnd := keyIdx >= len(keys)
		valEnd := valIdx >= len(values)
		if keyEnd != valEnd {
			panic("attributes keys and values count mismatch")
		}
		if keyEnd {
			break
		}

		keyIdx++
		valIdx++
		keyStart = keyIdx
		valStart = valIdx
	}

	return result
}

package equipment

import (
	"net/url"
	"strconv"
	"strings"

	"gno.land/p/jeronimoalbi/pager/v0"
)

func Render(iURL string) string {
	assertRenderURLLen(iURL)
	u, err := url.Parse(iURL)
	if err != nil {
		return renderEquipmentError("Invalid URL")
	}

	switch u.Path {
	case "":
		return renderEquipmentHome()
	case "owner":
		return renderEquipmentOwner(iURL, address(u.Query().Get("address")))
	default:
		return renderEquipmentError("Not found")
	}
}

func renderEquipmentHome() string {
	return `# AKKADIA Equipment

Look up equipment held by an address.

<gno-form path="owner">
  <gno-input name="address" placeholder="Enter the address" />
</gno-form>
`
}

func renderEquipmentOwner(iURL string, owner address) string {
	if !owner.IsValid() {
		return renderEquipmentError("Invalid address")
	}

	output := `# Equipment Holdings

[← Home](./equipment:)

* **Address**: ` + owner.String() + `
`

	total := GetOwnedCount(owner)
	output += "* **Total**: " + strconv.Itoa(total) + "\n\n"
	if total == 0 {
		return output + `*No equipment held.*
`
	}

	pageSize := 20
	if pageSize > listLimit {
		pageSize = listLimit
	}
	pages, err := pager.New(iURL, total, pager.WithPageSize(pageSize))
	if err != nil {
		return renderEquipmentError("Invalid page")
	}

	rows := ListByOwner(owner, pages.Page(), pages.PageSize())
	for _, row := range rows {
		output += formatEquipmentHolding(row)
	}
	if pages.HasPages() {
		output += "\n" + pager.Picker(pages)
	}
	return output
}

func formatEquipmentHolding(row map[string]string) string {
	line := "* **" + escapeEquipmentMarkdown(row[tokenIDKey]) + "**: definitionId " + escapeEquipmentMarkdown(row[definitionIDKey])
	for key, value := range row {
		if key == tokenIDKey || key == definitionIDKey || key == createdAtKey {
			continue
		}
		line += " · " + escapeEquipmentMarkdown(key) + " " + escapeEquipmentMarkdown(value)
	}
	return line + "\n"
}

func renderEquipmentError(message string) string {
	return `# Error

> ` + escapeEquipmentMarkdown(message) + `

[← Home](./equipment:)
`
}

func escapeEquipmentMarkdown(value string) string {
	value = strings.ReplaceAll(value, "\\", "\\\\")
	value = strings.ReplaceAll(value, "\n", "\\n")
	value = strings.ReplaceAll(value, "`", "\\`")
	value = strings.ReplaceAll(value, "*", "\\*")
	value = strings.ReplaceAll(value, "_", "\\_")
	value = strings.ReplaceAll(value, "{", "\\{")
	value = strings.ReplaceAll(value, "}", "\\}")
	value = strings.ReplaceAll(value, "[", "\\[")
	value = strings.ReplaceAll(value, "]", "\\]")
	value = strings.ReplaceAll(value, "(", "\\(")
	value = strings.ReplaceAll(value, ")", "\\)")
	value = strings.ReplaceAll(value, "#", "\\#")
	value = strings.ReplaceAll(value, "+", "\\+")
	value = strings.ReplaceAll(value, "-", "\\-")
	value = strings.ReplaceAll(value, ".", "\\.")
	value = strings.ReplaceAll(value, "!", "\\!")
	value = strings.ReplaceAll(value, "|", "\\|")
	value = strings.ReplaceAll(value, ">", "\\>")
	return value
}

package equipment

import "unicode/utf8"

const renderURLMaxRunes = 1024

func assertRenderURLLen(value string) {
	if utf8.RuneCountInString(value) > renderURLMaxRunes {
		panic("url exceeds max runes")
	}
}

package craft

import (
	"chain"
	"chain/banker"
	"chain/runtime/unsafe"
	"strconv"

	"gno.land/p/akkadia/beta/accesscontrol"
	"gno.land/p/nt/bptree/v0"
	"gno.land/r/akkadia/beta/admin"
	"gno.land/r/akkadia/beta/equipment"
	"gno.land/r/akkadia/beta/item"
)

const (
	SetRecipeEvent     = "SetRecipe"
	DeleteRecipeEvent  = "DeleteRecipe"
	DeleteRecipesEvent = "DeleteRecipes"
	SetListLimitEvent  = "SetListLimit"
	SetCraftFeeEvent   = "SetCraftFee"
	CraftEvent         = "Craft"
)

var (
	recipes   = bptree.NewBPTree32()
	listLimit = defaultRecipeListLimit
	craftFee  = defaultCraftFee
)

func init() { resetCraftState() }

func resetCraftState() {
	recipes = bptree.NewBPTree32()
	listLimit = defaultRecipeListLimit
	craftFee = defaultCraftFee
}

// SetRecipe stores the item definition ID produced by a canonical recipe.
func SetRecipe(cur realm, recipe string, itemID uint32) {
	accesscontrol.AssertIsAdmin(0, cur, admin.IsAdmin)
	assertCraftNoCoins()
	canonicalRecipe, _ := mustParseRecipe(recipe)
	setRecipe(canonicalRecipe, itemID)
}

// SetRecipes stores up to 100 canonical recipe and item ID pairs in one transaction.
func SetRecipes(cur realm, recipesCSV, itemIDsCSV string) {
	accesscontrol.AssertIsAdmin(0, cur, admin.IsAdmin)
	assertCraftNoCoins()
	canonicalRecipes, itemIDs := mustParseRecipeCSV(recipesCSV, itemIDsCSV)
	for i, recipe := range canonicalRecipes {
		setRecipe(recipe, itemIDs[i])
	}
}

func setRecipe(canonicalRecipe string, itemID uint32) {
	recipes.Set(canonicalRecipe, itemID)
	chain.Emit(
		SetRecipeEvent,
		"recipe", canonicalRecipe,
		"itemId", strconv.FormatUint(uint64(itemID), 10),
	)
}

func DeleteRecipe(cur realm, recipe string) {
	accesscontrol.AssertIsAdmin(0, cur, admin.IsAdmin)
	assertCraftNoCoins()
	canonicalRecipe := mustCanonicalRecipe(recipe)
	deleteRecipe(canonicalRecipe)
	chain.Emit(DeleteRecipeEvent, "recipe", canonicalRecipe)
}

func DeleteRecipes(cur realm, recipesCSV string) {
	accesscontrol.AssertIsAdmin(0, cur, admin.IsAdmin)
	assertCraftNoCoins()
	canonicalRecipes := mustParseRecipeKeyCSV(recipesCSV)
	for _, recipe := range canonicalRecipes {
		if !recipes.Has(recipe) {
			panic("recipe not found: " + recipe)
		}
	}
	for _, recipe := range canonicalRecipes {
		deleteRecipe(recipe)
	}
	chain.Emit(DeleteRecipesEvent, "count", strconv.Itoa(len(canonicalRecipes)))
}

func deleteRecipe(canonicalRecipe string) {
	if _, removed := recipes.Remove(canonicalRecipe); !removed {
		panic("recipe not found: " + canonicalRecipe)
	}
}

func HasRecipe(recipe string) bool {
	canonical, _, errMsg := parseRecipe(recipe)
	if errMsg != "" {
		return false
	}
	return recipes.Has(canonical)
}

func GetRecipe(recipe string) uint32 {
	return mustGetRecipeItemID(mustCanonicalRecipe(recipe))
}

func GetRecipeCount() int {
	return recipes.Size()
}

func ListRecipes(page, count int) []map[string]string {
	assertRecipeListPageCount(page, count)
	result := []map[string]string{}
	recipes.IterateByOffset((page-1)*count, count, func(recipe string, value any) bool {
		result = append(result, map[string]string{
			"recipe": recipe,
			"itemId": strconv.FormatUint(uint64(value.(uint32)), 10),
		})
		return false
	})
	return result
}

func SetListLimit(cur realm, limit int) {
	accesscontrol.AssertIsAdmin(0, cur, admin.IsAdmin)
	assertCraftNoCoins()
	if limit < 1 {
		panic("limit must be at least 1")
	}

	oldLimit := listLimit
	listLimit = limit
	chain.Emit(
		SetListLimitEvent,
		"oldLimit", strconv.Itoa(oldLimit),
		"newLimit", strconv.Itoa(limit),
	)
}

func GetListLimit() int {
	return listLimit
}

func SetCraftFee(cur realm, fee int64) {
	accesscontrol.AssertIsAdmin(0, cur, admin.IsAdmin)
	assertCraftNoCoins()
	if fee < 0 {
		panic("fee must be non-negative")
	}

	oldFee := craftFee
	craftFee = fee
	chain.Emit(
		SetCraftFeeEvent,
		"oldFee", strconv.FormatInt(oldFee, 10),
		"newFee", strconv.FormatInt(fee, 10),
	)
}

func GetCraftFee() int64 {
	return craftFee
}

// Craft burns a canonical recipe and mints the next GRC721 equipment token.
func Craft(cur realm, recipe string) uint64 {
	caller := accesscontrol.MustGetUserCaller(0, cur)
	canonicalRecipe, ingredients := mustParseRecipe(recipe)
	itemID := mustGetRecipeItemID(canonicalRecipe)
	assertExactUgnotPayment(craftFee)

	for _, ingredient := range ingredients {
		item.BurnFromRealm(cross(cur), caller, ingredient.TokenID, ingredient.Amount)
	}
	tokenID := equipment.MintFromRealm(cross(cur), caller, itemID, "", "")
	if craftFee > 0 {
		bnk := banker.NewBanker(banker.BankerTypeRealmSend, cur)
		bnk.SendCoins(cur.Address(), admin.GetFeeCollector(), chain.Coins{{"ugnot", craftFee}})
	}

	chain.Emit(
		CraftEvent,
		"owner", caller.String(),
		"recipe", canonicalRecipe,
		"equipmentTokenId", strconv.FormatUint(tokenID, 10),
		"itemId", strconv.FormatUint(uint64(itemID), 10),
		"fee", strconv.FormatInt(craftFee, 10),
	)
	return tokenID
}

func mustCanonicalRecipe(recipe string) string {
	canonical, _ := mustParseRecipe(recipe)
	return canonical
}

func mustGetRecipeItemID(recipe string) uint32 {
	value := recipes.Get(recipe)
	if value == nil {
		panic("recipe not found: " + recipe)
	}
	return value.(uint32)
}

func assertCraftNoCoins() {
	if len(unsafe.OriginSend()) != 0 {
		panic("attached coins not allowed")
	}
}

func assertExactUgnotPayment(expected int64) {
	coins := unsafe.OriginSend()
	if expected == 0 {
		if len(coins) != 0 {
			panic("exact payment required: expected no coins, got " + coins.String())
		}
		return
	}
	if len(coins) != 1 || coins[0].Denom != "ugnot" || coins[0].Amount != expected {
		panic("exact payment required: expected " + strconv.FormatInt(expected, 10) + "ugnot, got " + coins.String())
	}
}

package craft

import (
	"net/url"
	"strconv"
	"strings"
)

func Render(iURL string) string {
	u, err := url.Parse(iURL)
	if err != nil {
		return renderRecipeError("Invalid URL")
	}

	switch u.Path {
	case "":
		return renderRecipeHome()
	case "recipe":
		return renderRecipeResult(u.Query().Get("recipe"))
	case "recipes":
		return renderRecipeList(u.Query().Get("page"))
	default:
		return renderRecipeError("Not found")
	}
}

func renderRecipeHome() string {
	return `# AKKADIA Recipe

Ingredients are bound to occupied occupancy bits from slot 0 upward.

Current craft fee is ` + strconv.FormatInt(GetCraftFee(), 10) + `ugnot.

Enter a recipe to find its item ID.

<gno-form path="recipe">
  <gno-input name="recipe" placeholder="0013|iron:1|iron:2|stick:3" />
</gno-form>

* [Browse Recipes](./craft:recipes)
`
}

func renderRecipeList(rawPage string) string {
	page := 1
	if rawPage != "" {
		parsed, err := strconv.Atoi(rawPage)
		if err != nil || parsed < 1 {
			return renderRecipeError("Invalid page")
		}
		page = parsed
	}

	count := 20
	if count > listLimit {
		count = listLimit
	}

	output := `# Recipes

[← Back](./craft:)

`
	total := GetRecipeCount()
	if total == 0 {
		return output + `*No recipes stored yet.*
`
	}

	rows := ListRecipes(page, count)
	if len(rows) == 0 {
		return renderRecipeError("Invalid page")
	}
	for _, row := range rows {
		output += "* " + formatRecipeCode(row["recipe"]) + " → " + row["itemId"] + "\n"
	}
	return output
}

func renderRecipeResult(recipe string) string {
	if recipe == "" {
		return renderRecipeError("Recipe is required")
	}

	canonical, _, errMsg := parseRecipe(recipe)
	if errMsg != "" {
		return renderRecipeError("Invalid recipe")
	}
	if !recipes.Has(canonical) {
		return renderRecipeError("Recipe not found")
	}

	return `# Recipe Result

* **Recipe**: ` + formatRecipeCode(canonical) + `
* **Item ID**: ` + strconv.FormatUint(uint64(mustGetRecipeItemID(canonical)), 10) + `

[← Back](./craft:)
`
}

func renderRecipeError(message string) string {
	return `# Error

> ` + message + `

[← Back](./craft:)
`
}

// Recipes use | and - as syntax. A code span keeps those characters
// literal so gnoweb does not show backslash escapes.
func formatRecipeCode(recipe string) string {
	recipe = strings.ReplaceAll(recipe, "\n", " ")
	fence := "`"
	for strings.Contains(recipe, fence) {
		fence += "`"
	}
	return fence + recipe + fence
}

